sys_security_acl.script:
// Se o usuário for admin, concede acesso total
if (gs.hasRole('x_1546361_bases.admin - bases')) {
    answer = true;
} else {
    // Verifica se o registro de Access Registration tem uma base associada
    if (!current.base.nil()) {
        var baseGR = new GlideRecord('x_1546361_bases_bases'); // Consulta a tabela Bases

        // Busca a base associada ao registro de Access Registration
        baseGR.addQuery('sys_id', current.base); 
        baseGR.query();

        if (baseGR.next()) { 
            // Verifica se o usuário logado é o assigned_to (manager) da base associada ao registro
            answer = (baseGR.assigned_to == gs.getUserID());
        } else {
            answer = false; // Se a base não for encontrada, bloqueia o acesso
        }
    } else {
        answer = false; // Se o registro de Access Registration não tiver uma base associada, bloqueia
    }
}
